function resourcesView(){const items=window.EdmundResources.items;$('#plannerbody').innerHTML='<h2>Passende Angebote von Edmund</h2><p>Spiele, Kurse und Erklärungen für deine Schachstunde. Jedes Angebot hat einen direkt nutzbaren Arbeitsauftrag.</p>'+resourceNote()+'<label>Angebot suchen<input id="resourcesearch" type="search" placeholder="Zum Beispiel Eröffnung, Endspiel oder Quiz"></label><div id="resourcecards" class="grid"></div>';function draw(){const q=$('#resourcesearch').value.toLocaleLowerCase();const filtered=items.filter(x=>(x.title+' '+x.prior+' '+x.phase+' '+x.work).toLocaleLowerCase().includes(q));$('#resourcecards').innerHTML=resourceCards(filtered)||'<p>Kein passendes Angebot gefunden.</p>'}$('#resourcesearch').oninput=draw;draw()}
