function exportHTML(kind,count,all){const p=current(),old=si,idx=all?p.sessions.map((_,i)=>i):[si];let css='',out='',src='';try{for(const i of idx){si=i;const x=sheetParts(session(),count);css=x.css;src=x.sources;
if(kind==='plan')out+=x.plan;else if(kind==='worksheet')out+=x.sheet;else if(kind==='solutions')out+=x.teacher+x.extraPage;else if(kind==='check')out+=x.lc||'<div class="ws-page">'+x.head('Lerncheck')+'<p>Für diesen Termin ist keine Lerncheck-Aufgabe hinterlegt.</p></div>';
else{const inner=blocksHTML(materialBlocks(kind,count,false));out+=kind==='planfull'?'<div class="printsection landscape ws-doc ws-docwide">'+inner+'</div>':'<div class="ws-page ws-doc">'+x.head(docSubs[kind]||'Material')+inner+'</div>'}}}finally{si=old}return css+docCSS+out+(['plan','planfull','prep'].includes(kind)?'':src)}

function lessonPackage(){const keep=materialPhase,s=session(),idx=n=>{const i=s.phases.findIndex(x=>x.name.startsWith(n));return i<0?null:i};const out=[{section:'landscape'},...materialBlocks('plan',4,false)];
const clean=(part,kind)=>part.filter((x,i)=>i>1&&!x.page&&!(x.h===2&&x.text===s.title)&&!/^(Figuren: Cburnett|Eigene |Quelle: )/.test(String(x.text||''))&&!(x.text===''&&!x.lead)&&!(['hints','solutions'].includes(kind)&&(x.fen||x.labyrinth)));
const add=(title,kind,phase,count)=>{materialPhase=phase;const part=clean(materialBlocks(kind,count),kind);materialPhase=keep;if(part.some(x=>x.fen||x.labyrinth||x.text))out.push({h:2,text:title,newpage:!out.at(-1)?.section},...part)};
out.push({section:'portrait'});const er=idx('Erarbeitung'),ex=s.exercises;add('Material 1 · Einstieg und Erarbeitung (Aufgaben 1 und 2)','worksheet',er,2);add('Material 2 · Arbeitsblatt Übung','worksheet',idx('Übung'),/maze/.test(s.topic||'')?5:4);add('Material 3 · Lerncheck','check',idx('Lerncheck'),1);add('Für die Lehrkraft · Hilfekarten','hints',idx('Übung'),4);add('Für die Lehrkraft · Lösungen','solutions',null,6);
out.push({text:'Figuren: Cburnett und Mitwirkende, Wikimedia Commons, CC BY-SA 3.0. Aufgaben: Lichess-Datenbank (CC0). Einzelquellen: LICENSES.html.'});return out}
function materials(){restoreNext=true;$('#plannerbody').innerHTML=`<h3>Materialien & Export</h3><p>Schülerblätter und Lösungen sind getrennte Ausgaben. PDF wird über den Browserdruck erzeugt. </p><div class="formgrid">${select('exportkind','Dokument',[['plan','Kompakter Stundenverlauf (Lehrkraft)'],['planfull','Ausführlicher Stundenverlauf (Lehrkraft)'],['prep','Material- und Vorbereitungsliste'],['worksheet','Arbeitsblatt ohne Lösungen'],['solutions','Separates Lösungsblatt'],['stations','Stationskarten'],['hints','Abgestufte Hilfekarten'],['check','Kurzer Lerncheck ohne Lösungen']],'worksheet')}${select('exportcount','Aufgabenanzahl',[2,4,6],4)}${select('exportscope','Umfang',[['one','Aktueller Termin'],['all','Alle Termine der Reihe']],'one')}</div><div class="row"><button class="primary" id="exportprint">Druckvorschau / PDF über Browserdruck</button><button id="returneditor">← Zur Stundenplanung</button></div><p id="exportstatus" role="status"></p><details><summary>Transparente Auswertung</summary><p>Taktiklösungen stammen aus den belegten Lichess-Datensätzen. Eigene Regelübungen haben gesonderte Lösungshinweise. Freie Erklärungen und Entwürfe beurteilt die Lehrkraft. Eine automatische Bewertung schriftlicher Antworten findet nicht statt.</p></details>`;const data=()=>{const k=$('#exportkind').value,blocks=materialBlocks(k,+$('#exportcount').value,$('#exportscope').value==='all');return ['plan','planfull'].includes(k)?[{section:'landscape'},...blocks]:blocks};$('#exportprint').onclick=()=>{bridge.printContent(exportHTML($('#exportkind').value,+$('#exportcount').value,$('#exportscope').value==='all'));try{fitPages()}catch(e){}};$('#returneditor').onclick=editor}
async function pngBoard(fen){const g=new bridge.Chess(fen),size=400,pad=24,cell=44;let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400"><rect width="400" height="400" fill="white"/>`;for(let r=8;r>=1;r--)for(let f=0;f<8;f++){const x=pad+f*cell,y=pad+(8-r)*cell,p=g.get('abcdefgh'[f]+r);svg+=`<rect x="${x}" y="${y}" width="44" height="44" fill="${(f+r)%2?'#b8b8b8':'#fff'}" stroke="#777" stroke-width=".4"/>`;if(p){const name=`Chess_${p.type}${p.color==='w'?'l':'d'}t45.svg`;let raw=atob(window.FIGURE_DATA[name].split(',')[1]);raw=raw.slice(raw.indexOf('<svg'));const inner=raw.slice(raw.indexOf('>')+1,raw.lastIndexOf('</svg>'));svg+=`<g transform="translate(${x},${y}) scale(${cell/45})">${inner}</g>`}}for(let i=0;i<8;i++){svg+=`<text x="${pad+i*cell+22}" y="17" text-anchor="middle" font-size="13">${'abcdefgh'[i]}</text><text x="${pad+i*cell+22}" y="393" text-anchor="middle" font-size="13">${'abcdefgh'[i]}</text><text x="12" y="${pad+i*cell+27}" text-anchor="middle" font-size="13">${8-i}</text><text x="388" y="${pad+i*cell+27}" text-anchor="middle" font-size="13">${8-i}</text>`}svg+='</svg>';const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=400;canvas.height=400;canvas.getContext('2d').drawImage(img,0,0);const b=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!b)throw Error('Diagramm konnte nicht erzeugt werden.');return new Uint8Array(await b.arrayBuffer())}finally{URL.revokeObjectURL(url)}}
async function pngLab(lab){const url=URL.createObjectURL(new Blob([window.Labyrinth.svg(lab)],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=400;canvas.height=400;canvas.getContext('2d').drawImage(img,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Labyrinthdiagramm konnte nicht erzeugt werden.');return new Uint8Array(await blob.arrayBuffer())}finally{URL.revokeObjectURL(url)}}
async function word(blocks,landscape){const d=await loadScript('docx.js','docx');const sections=[];let children=[],orient=landscape;const flush=()=>{if(children.length)sections.push({properties:{page:{size:{orientation:orient?d.PageOrientation.LANDSCAPE:d.PageOrientation.PORTRAIT},margin:{top:700,bottom:700,left:700,right:700}}},children});children=[]};for(const b of blocks){if(b.section){flush();orient=b.section==='landscape';continue}if(b.h===2&&b.newpage)children.push(new d.Paragraph({children:[new d.PageBreak()]}));if(b.lead!==undefined){children.push(new d.Paragraph({children:[new d.TextRun({text:b.lead,bold:true}),...(b.text?[new d.TextRun({text:' '+b.text})]:[])],spacing:{after:80}}));continue}if(b.page){children.push(new d.Paragraph({children:[new d.PageBreak()]}));continue}if(b.fen||b.labyrinth){try{children.push(new d.Paragraph({children:[new d.ImageRun({type:'png',data:b.labyrinth?await pngLab(b.labyrinth):await pngBoard(b.fen),transformation:{width:orient===false&&sections.length?170:230,height:orient===false&&sections.length?170:230}})],keepNext:true}));}catch(e){children.push(new d.Paragraph({text:b.fen?'Diagramm (FEN): '+b.fen:'Labyrinth-Diagramm'}))}continue}if(b.table){children.push(new d.Table({width:{size:100,type:d.WidthType.PERCENTAGE},rows:b.table.map((r,i)=>new d.TableRow({tableHeader:i===0,cantSplit:true,children:r.map((c,ci)=>new d.TableCell({...(b.widths?{width:{size:b.widths[ci],type:d.WidthType.PERCENTAGE}}:{}),children:String(c).split('\n').map(t=>new d.Paragraph({children:[new d.TextRun({text:t,bold:i===0,size:20})]}))}))}))}));continue}children.push(new d.Paragraph({text:b.text||'',heading:b.h?d.HeadingLevel['HEADING_'+Math.min(b.h,3)]:undefined,keepNext:!!b.h,spacing:{after:120}}))}flush();const doc=new d.Document({creator:'SchachStunde',title:current().title,styles:{default:{document:{run:{font:'Arial',size:22}}}},sections});download(await d.Packer.toBlob(doc),'SchachStunde-'+(landscape?'Verlaufsplan':'Material')+'.docx')}

