function scanText(text){const parts=String(text||'').split(/(?<=[.!?])\s+/);let out=parts[0]||'';for(let i=1;i<parts.length&&(/^\d+\.$/.test(out.trim())||out.length<12);i++)out+=' '+parts[i];return out.replace(/^\d+\.\s*/,'')||'Noch ergänzen';}
function scanValue(ph,key){return ph['scan_'+key]||scanText(ph[key]);}
function phaseTone(name){return /Einstieg|Warm/.test(name)?'entry':/Sicherung/.test(name)?'secure':/Erarbeitung|Theorie/.test(name)?'learn':/Abschluss|Lerncheck/.test(name)?'close':/Übung|Anwendung|Transfer/.test(name)?'practice':'organise';}
function reserves(s){return {fast:s.reserveFast||'Eine weitere Aufgabe zum gleichen Lernziel ohne Hilfe lösen; eine zweite Idee prüfen und begründen. Partnerrollen tauschen.',short:s.reserveShort||'Eine Wiederholungsaufgabe weglassen und Spielzeit kürzen. Ergebnissicherung, einen kurzen individuellen Lerncheck und Aufräumen beibehalten.'};}
